"""Synthetic StatsBomb open-data tree for tests.

Generated by code; no real provider data. It mimics the schema of StatsBomb's open data
(competitions, matches, events, lineups, three-sixty) closely enough for Rondo's ingest and
socceraction's loader. Two matches; the first has 360 frames.

Known by construction, per match (both periods: 46:00 and 48:00, so 94 minutes):
- home 1-1 away: an open-play home goal, and an own goal by a home defender;
- home player X11 is substituted at 65:00 on the clock by X12 (66 and 28 elapsed minutes);
- away player X07 is sent off at 76:00 on the clock, after 77 elapsed minutes;
- one home penalty (missed, no freeze frame) and one pass with outcome "Injury Clearance".
"""

from __future__ import annotations

import json
import uuid
from pathlib import Path
from typing import Any

from rondo.core.scope import CompetitionSeason

COMPETITION_ID, SEASON_ID = 9999, 1
MATCH_IDS = (900001, 900002)
HOME, AWAY = 1001, 1002
PERIOD_LENGTH_S = {1: 46 * 60.0, 2: 48 * 60.0}
FIXTURE_SCOPE = (CompetitionSeason(COMPETITION_ID, SEASON_ID, "core", "fixture", 2, 1),)

# 4-4-2: (position_id, position name)
FORMATION = [
    (1, "Goalkeeper"),
    (2, "Right Back"),
    (3, "Right Center Back"),
    (5, "Left Center Back"),
    (6, "Left Back"),
    (12, "Right Midfield"),
    (13, "Right Center Midfield"),
    (15, "Left Center Midfield"),
    (16, "Left Midfield"),
    (22, "Right Center Forward"),
    (24, "Left Center Forward"),
]


def pid(team: int, n: int) -> int:
    """Player id for shirt slot ``n`` (1-13) of ``team``."""
    return (100 if team == HOME else 200) + n


def _ts(seconds: float) -> str:
    h, rem = divmod(seconds, 3600)
    m, s = divmod(rem, 60)
    return f"{int(h):02d}:{int(m):02d}:{s:06.3f}"


def _ref(i: int, name: str) -> dict[str, Any]:
    return {"id": i, "name": name}


def _team(t: int) -> dict[str, Any]:
    return _ref(t, "Home FC" if t == HOME else "Away FC")


def _player(t: int, n: int) -> dict[str, Any]:
    return _ref(pid(t, n), f"{'Home' if t == HOME else 'Away'} Player {n}")


def _position(n: int) -> dict[str, Any]:
    return _ref(*FORMATION[n - 1]) if n <= 11 else _ref(*FORMATION[10])


class _Events:
    def __init__(self, match_id: int) -> None:
        self.match_id = match_id
        self.rows: list[dict[str, Any]] = []
        self.possession = 1

    def add(
        self,
        type_id: int,
        type_name: str,
        period: int,
        ts: float,
        team: int,
        n: int | None = None,
        loc: list[float] | None = None,
        **extra: Any,
    ) -> str:
        eid = str(uuid.uuid5(uuid.NAMESPACE_URL, f"rondo-fixture/{self.match_id}/{len(self.rows)}"))
        clock = ts + (45 * 60 if period == 2 else 0)
        e: dict[str, Any] = {
            "id": eid,
            "index": len(self.rows) + 1,
            "period": period,
            "timestamp": _ts(ts),
            "minute": int(clock // 60),
            "second": int(clock % 60),
            "type": _ref(type_id, type_name),
            "possession": self.possession,
            "possession_team": _team(team),
            "play_pattern": _ref(1, "Regular Play"),
            "team": _team(team),
        }
        if n is not None:
            e["player"] = _player(team, n)
            e["position"] = _position(n)
            e["related_events"] = []
        if loc is not None:
            e["location"] = loc
        e.update(extra)
        self.rows.append(e)
        return eid


def build_events(match_id: int) -> list[dict[str, Any]]:
    """All events for one synthetic match, in order."""
    ev = _Events(match_id)
    for t in (HOME, AWAY):
        lineup = [
            {"player": _player(t, n), "position": _position(n), "jersey_number": n}
            for n in range(1, 12)
        ]
        ev.add(35, "Starting XI", 1, 0.0, t, tactics={"formation": 442, "lineup": lineup})
    for t in (HOME, AWAY):
        ev.add(18, "Half Start", 1, 0.0, t)

    # Home attack ending in a goal.
    ev.add(
        30,
        "Pass",
        1,
        1.0,
        HOME,
        10,
        [60.0, 40.0],
        duration=1.0,
        **{
            "pass": {
                "recipient": _player(HOME, 11),
                "length": 14.1,
                "angle": -0.79,
                "height": _ref(1, "Ground Pass"),
                "end_location": [70.0, 30.0],
                "type": _ref(65, "Kick Off"),
                "body_part": _ref(40, "Right Foot"),
            }
        },
        play_pattern=_ref(9, "From Kick Off"),
    )
    ev.add(42, "Ball Receipt*", 1, 2.0, HOME, 11, [70.0, 30.0])
    ev.add(
        43,
        "Carry",
        1,
        2.5,
        HOME,
        11,
        [70.0, 30.0],
        duration=3.0,
        carry={"end_location": [80.0, 32.0]},
    )
    ev.add(17, "Pressure", 1, 3.0, AWAY, 5, [40.0, 48.0], duration=1.5, counterpress=True)
    key = ev.add(
        30,
        "Pass",
        1,
        6.0,
        HOME,
        11,
        [80.0, 32.0],
        duration=1.2,
        under_pressure=True,
        **{
            "pass": {
                "recipient": _player(HOME, 10),
                "length": 30.6,
                "angle": 0.2,
                "height": _ref(1, "Ground Pass"),
                "end_location": [110.0, 38.0],
                "body_part": _ref(38, "Left Foot"),
                "shot_assist": True,
                "goal_assist": True,
            }
        },
    )
    ev.add(42, "Ball Receipt*", 1, 7.0, HOME, 10, [110.0, 38.0])
    frame = [
        {
            "location": [116.0, 40.0],
            "player": _player(AWAY, 1),
            "position": _position(1),
            "teammate": False,
        },
        {
            "location": [112.0, 36.0],
            "player": _player(AWAY, 3),
            "position": _position(3),
            "teammate": False,
        },
        {
            "location": [108.0, 44.0],
            "player": _player(HOME, 9),
            "position": _position(9),
            "teammate": True,
        },
    ]
    sid = ev.add(
        16,
        "Shot",
        1,
        8.0,
        HOME,
        10,
        [110.0, 38.0],
        duration=0.5,
        shot={
            "statsbomb_xg": 0.41,
            "end_location": [120.0, 39.5, 1.2],
            "key_pass_id": key,
            "body_part": _ref(40, "Right Foot"),
            "type": _ref(87, "Open Play"),
            "outcome": _ref(97, "Goal"),
            "technique": _ref(93, "Normal"),
            "first_time": True,
            "freeze_frame": frame,
        },
    )
    ev.rows[-3]["pass"]["assisted_shot_id"] = sid  # the key pass, two events before the shot
    ev.possession += 1

    # Away restart, a tackle, an interception, clearance, recovery, foul with a yellow card.
    ev.add(
        30,
        "Pass",
        1,
        60.0,
        AWAY,
        10,
        [60.0, 40.0],
        duration=1.0,
        **{
            "pass": {
                "recipient": _player(AWAY, 8),
                "length": 10.0,
                "angle": 3.14,
                "height": _ref(1, "Ground Pass"),
                "end_location": [50.0, 40.0],
                "type": _ref(65, "Kick Off"),
                "body_part": _ref(40, "Right Foot"),
            }
        },
    )
    ev.add(
        4,
        "Duel",
        1,
        70.0,
        AWAY,
        4,
        [30.0, 40.0],
        duel={"type": _ref(11, "Tackle"), "outcome": _ref(4, "Won")},
    )
    ev.add(
        10, "Interception", 1, 80.0, HOME, 3, [35.0, 30.0], interception={"outcome": _ref(4, "Won")}
    )
    ev.add(
        9,
        "Clearance",
        1,
        90.0,
        AWAY,
        3,
        [10.0, 40.0],
        clearance={"body_part": _ref(37, "Head"), "head": True},
    )
    ev.add(2, "Ball Recovery", 1, 100.0, HOME, 6, [55.0, 20.0])
    ev.add(
        22,
        "Foul Committed",
        1,
        110.0,
        AWAY,
        6,
        [50.0, 60.0],
        foul_committed={"card": _ref(7, "Yellow Card")},
    )
    ev.add(21, "Foul Won", 1, 110.0, HOME, 7, [70.0, 20.0])
    ev.add(
        30,
        "Pass",
        1,
        200.0,
        HOME,
        2,
        [40.0, 75.0],
        duration=0.5,
        **{
            "pass": {
                "length": 5.0,
                "angle": 1.0,
                "height": _ref(1, "Ground Pass"),
                "end_location": [42.0, 79.0],
                "outcome": _ref(74, "Injury Clearance"),
                "body_part": _ref(40, "Right Foot"),
            }
        },
    )
    # Away shot, saved by the home keeper.
    ev.possession += 1
    frame2 = [
        {
            "location": [117.0, 40.0],
            "player": _player(HOME, 1),
            "position": _position(1),
            "teammate": False,
        },
        {
            "location": [104.0, 42.0],
            "player": _player(HOME, 4),
            "position": _position(4),
            "teammate": False,
        },
    ]
    ev.add(
        16,
        "Shot",
        1,
        900.0,
        AWAY,
        9,
        [100.0, 40.0],
        duration=0.6,
        shot={
            "statsbomb_xg": 0.08,
            "end_location": [118.0, 41.0, 0.5],
            "body_part": _ref(38, "Left Foot"),
            "type": _ref(87, "Open Play"),
            "outcome": _ref(100, "Saved"),
            "technique": _ref(93, "Normal"),
            "freeze_frame": frame2,
        },
    )
    ev.add(
        23,
        "Goal Keeper",
        1,
        901.0,
        HOME,
        1,
        [2.0, 40.0],
        goalkeeper={
            "type": _ref(33, "Shot Saved"),
            "outcome": _ref(15, "Success"),
            "position": _ref(44, "Set"),
            "body_part": _ref(35, "Both Hands"),
        },
    )
    for t in (HOME, AWAY):
        ev.add(34, "Half End", 1, PERIOD_LENGTH_S[1], t)

    # Second half.
    for t in (HOME, AWAY):
        ev.add(18, "Half Start", 2, 0.0, t)
    ev.add(
        16,
        "Shot",
        2,
        600.0,
        HOME,
        11,
        [108.0, 40.0],
        duration=0.4,
        shot={
            "statsbomb_xg": 0.78,
            "end_location": [120.0, 46.0, 2.9],
            "body_part": _ref(40, "Right Foot"),
            "type": _ref(88, "Penalty"),
            "outcome": _ref(98, "Off T"),
            "technique": _ref(93, "Normal"),
        },
        play_pattern=_ref(4, "From Free Kick"),
    )
    ev.add(
        19,
        "Substitution",
        2,
        20 * 60.0,
        HOME,
        11,
        substitution={"outcome": _ref(103, "Tactical"), "replacement": _player(HOME, 12)},
    )
    ev.add(24, "Bad Behaviour", 2, 31 * 60.0, AWAY, 7, bad_behaviour={"card": _ref(5, "Red Card")})
    ev.add(20, "Own Goal Against", 2, 33 * 60.0, HOME, 4, [6.0, 38.0])
    ev.add(25, "Own Goal For", 2, 33 * 60.0, AWAY, 9, [114.0, 42.0])
    ev.add(
        30,
        "Pass",
        2,
        34 * 60.0,
        AWAY,
        10,
        [60.0, 40.0],
        duration=1.0,
        **{
            "pass": {
                "recipient": _player(AWAY, 8),
                "length": 12.0,
                "angle": 3.0,
                "height": _ref(2, "Low Pass"),
                "end_location": [48.0, 41.0],
                "outcome": _ref(9, "Incomplete"),
                "body_part": _ref(40, "Right Foot"),
            }
        },
    )
    for t in (HOME, AWAY):
        ev.add(34, "Half End", 2, PERIOD_LENGTH_S[2], t)
    return ev.rows


def build_lineups() -> list[dict[str, Any]]:
    """Lineups for both teams (same for both matches)."""
    out = []
    for t in (HOME, AWAY):
        players = []
        for n in range(1, 14 if t == HOME else 13):
            spells: list[dict[str, Any]] = []
            cards: list[dict[str, Any]] = []
            if n <= 11:
                end, to, to_p = "Final Whistle", None, None
                if t == HOME and n == 11:
                    end, to, to_p = "Substitution - Off (Tactical)", "65:00", 2
                if t == AWAY and n == 7:
                    end, to, to_p = "Red Card", "76:00", 2
                    cards = [
                        {
                            "time": "76:00",
                            "card_type": "Red Card",
                            "reason": "Violent Conduct",
                            "period": 2,
                        }
                    ]
                if t == AWAY and n == 6:
                    cards = [
                        {
                            "time": "01:50",
                            "card_type": "Yellow Card",
                            "reason": "Foul Committed",
                            "period": 1,
                        }
                    ]
                pos_id, pos_name = FORMATION[n - 1]
                spells.append(
                    {
                        "position_id": pos_id,
                        "position": pos_name,
                        "from": "00:00",
                        "to": to,
                        "from_period": 1,
                        "to_period": to_p,
                        "start_reason": "Starting XI",
                        "end_reason": end,
                    }
                )
            elif t == HOME and n == 12:
                spells.append(
                    {
                        "position_id": 24,
                        "position": "Left Center Forward",
                        "from": "65:00",
                        "to": None,
                        "from_period": 2,
                        "to_period": None,
                        "start_reason": "Substitution - On (Tactical)",
                        "end_reason": "Final Whistle",
                    }
                )
            players.append(
                {
                    "player_id": pid(t, n),
                    "player_name": _player(t, n)["name"],
                    "player_nickname": None,
                    "jersey_number": n,
                    "country": _ref(1, "Testland"),
                    "cards": cards,
                    "positions": spells,
                }
            )
        out.append({"team_id": t, "team_name": _team(t)["name"], "lineup": players})
    return out


def build_360(events: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """360 frames for the events that have a location (rectangle visible areas)."""
    frames = []
    for e in events:
        if "location" not in e or "player" not in e:
            continue
        x, y = e["location"]
        frames.append(
            {
                "event_uuid": e["id"],
                "visible_area": [
                    max(x - 30, 0),
                    0.0,
                    min(x + 30, 120),
                    0.0,
                    min(x + 30, 120),
                    80.0,
                    max(x - 30, 0),
                    80.0,
                    max(x - 30, 0),
                    0.0,
                ],
                "freeze_frame": [
                    {"teammate": True, "actor": True, "keeper": False, "location": [x, y]},
                    {
                        "teammate": False,
                        "actor": False,
                        "keeper": False,
                        "location": [min(x + 5, 120), min(y + 3, 80)],
                    },
                ],
            }
        )
    return frames


def write(root: Path) -> Path:
    """Write the synthetic open-data tree under ``root``; return the checkout path."""
    data = root / "open-data" / "data"
    for sub in ("matches", "events", "lineups", "three-sixty"):
        (data / sub).mkdir(parents=True, exist_ok=True)
    (data / "competitions.json").write_text(
        json.dumps(
            [
                {
                    "competition_id": COMPETITION_ID,
                    "season_id": SEASON_ID,
                    "country_name": "Testland",
                    "competition_name": "Fixture League",
                    "competition_gender": "male",
                    "competition_youth": False,
                    "competition_international": False,
                    "season_name": "2099/2100",
                    "match_updated": "2099-01-01T00:00:00",
                    "match_updated_360": None,
                    "match_available_360": None,
                    "match_available": "2099-01-01T00:00:00",
                }
            ]
        )
    )
    matches = []
    for i, mid in enumerate(MATCH_IDS):
        matches.append(
            {
                "match_id": mid,
                "match_date": f"2099-08-{10 + i:02d}",
                "kick_off": "15:00:00.000",
                "competition": {
                    "competition_id": COMPETITION_ID,
                    "country_name": "Testland",
                    "competition_name": "Fixture League",
                },
                "season": {"season_id": SEASON_ID, "season_name": "2099/2100"},
                "home_team": {
                    "home_team_id": HOME,
                    "home_team_name": "Home FC",
                    "home_team_gender": "male",
                    "home_team_group": None,
                    "country": _ref(1, "Testland"),
                    "managers": [],
                },
                "away_team": {
                    "away_team_id": AWAY,
                    "away_team_name": "Away FC",
                    "away_team_gender": "male",
                    "away_team_group": None,
                    "country": _ref(1, "Testland"),
                    "managers": [],
                },
                "home_score": 1,
                "away_score": 1,
                "match_status": "available",
                "match_status_360": "available" if i == 0 else "unscheduled",
                "last_updated": "2099-01-01T00:00:00",
                "last_updated_360": None,
                "metadata": {
                    "data_version": "1.1.0",
                    "shot_fidelity_version": "2",
                    "xy_fidelity_version": "2",
                },
                "match_week": i + 1,
                "competition_stage": _ref(1, "Regular Season"),
                "stadium": _ref(1, "Fixture Park"),
                "referee": _ref(1, "A Referee"),
            }
        )
        events = build_events(mid)
        (data / "events" / f"{mid}.json").write_text(json.dumps(events))
        (data / "lineups" / f"{mid}.json").write_text(json.dumps(build_lineups()))
        if i == 0:
            (data / "three-sixty" / f"{mid}.json").write_text(json.dumps(build_360(events)))
    (data / "matches" / str(COMPETITION_ID)).mkdir(parents=True, exist_ok=True)
    (data / "matches" / str(COMPETITION_ID) / f"{SEASON_ID}.json").write_text(json.dumps(matches))
    return root / "open-data"
